import numpy as np, os, json

run_info = {}
for i in range(1, 20):
    p = f"/work/fwd/r{i}/run.npz"
    if not os.path.exists(p):
        continue
    d = np.load(p)
    l0_ablated = 'L0_MLP' in d.files and np.allclose(d['L0_MLP'], 0, atol=1e-4)
    l1h0_ablated = 'L1H0_ATTN' in d.files and np.allclose(d['L1H0_ATTN'], 0, atol=1e-4)
    run_info[i] = {
        'shape': list(d['logits'].shape),
        'l0_ablated': l0_ablated,
        'l1h0_ablated': l1h0_ablated,
        'files': sorted(d.files)
    }

print(json.dumps(run_info, indent=2))

